// Step 1 — Ingestion: normalize the webhook payload into one canonical shape.
// Mode: Run Once for Each Item
const body = $json.body ?? $json;               // webhook puts the POST body under .body
const message = String(body.message ?? body.text ?? '').trim();
const source = String(body.source ?? 'Unknown').trim();

if (!message) {
  throw new Error('Payload must include a non-empty "message" field');
}

const requestId = body.id
  ? String(body.id)
  : 'REQ-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();

return {
  json: {
    request_id: requestId,
    source,
    customer: body.customer ?? null,
    received_at: body.received_at ?? new Date().toISOString(),
    raw_message: message,
  },
};

// Step 2a — build the classification request (prompt lives here so it is versioned with the workflow).
// Mode: Run Once for Each Item
const PROMPT_VERSION = 'classify-v3';

const SYSTEM_PROMPT = `You are the intake classifier for ArcVault, a B2B software company. You read ONE inbound customer message and classify it for routing. You never reply to the customer.

## Categories — choose exactly one
- "Bug Report": a specific product function behaves incorrectly (errors, wrong results, broken feature) for this customer or account, while the service as a whole is up.
- "Feature Request": asks for a capability that does not exist yet, or an enhancement to an existing one.
- "Billing Issue": invoices, charges, pricing, refunds, contract rates, payment methods, seats/licences.
- "Technical Question": "how do I / is it possible / do you support" questions about using, configuring or integrating the product. Nothing is reported as broken.
- "Incident/Outage": the service or a major part of it is unavailable or severely degraded for multiple users or a whole organisation, or the customer describes it as down / an outage.

Tie-breakers:
- Broken for many users or a whole org -> "Incident/Outage", not "Bug Report".
- Asking whether something is possible -> "Technical Question", even if the honest answer might be "not yet".
- Money mentioned only in passing does not make a message "Billing Issue".

## Priority
- "High": the customer is blocked from using the product or a core workflow (cannot log in, service down, data loss), multiple users are affected, or there is a security concern.
- "Medium": a real problem with limited impact or a workaround; disputed or incorrect charges; a question blocking a near-term purchase or rollout.
- "Low": requests, general questions and nice-to-haves with no current impact.

## Confidence (0.0-1.0) — how sure you are of the CATEGORY
- 0.90-1.00: unambiguous, exactly one category fits.
- 0.70-0.89: one category clearly dominates, a second is conceivable.
- 0.50-0.69: two categories are about equally plausible.
- below 0.50: the message is too vague or off-topic to classify.
Do not default to high confidence; use the full range.

## Output
Return ONLY a JSON object with these keys, in this order:
{"rationale": "<one sentence citing the words in the message that decided it>",
 "category": "<one of the five category strings, exactly as written above>",
 "secondary_category": "<the next most plausible category, or null>",
 "priority": "High" | "Medium" | "Low",
 "confidence": <number between 0 and 1>}

## Examples (not real customers)
Message: "The CSV export button gives an empty file when the date range spans two months."
{"rationale": "A specific feature (CSV export) returns wrong output for a particular input.", "category": "Bug Report", "secondary_category": null, "priority": "Medium", "confidence": 0.93}

Message: "Is it possible to schedule reports through the API, or would that need to be built?"
{"rationale": "Asks whether a capability exists; could become a feature request if it does not.", "category": "Technical Question", "secondary_category": "Feature Request", "priority": "Low", "confidence": 0.74}

Message: "Nobody in our org can upload files since 9am, timeouts everywhere."
{"rationale": "Whole organisation blocked from a core function since a specific time.", "category": "Incident/Outage", "secondary_category": "Bug Report", "priority": "High", "confidence": 0.95}`;

let model = 'gpt-4.1-mini';
try { if ($env.LLM_MODEL) model = $env.LLM_MODEL; } catch (e) { /* env access blocked: use default */ }

return {
  json: {
    ...$json,
    prompt_versions: { classification: PROMPT_VERSION },
    llm_request: {
      model,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: `Source channel: ${$json.source}\nMessage:\n"""\n${$json.raw_message}\n"""` },
      ],
    },
  },
};

// Step 2b — parse + validate the classifier output. Never throws: a bad LLM response
// becomes confidence 0 with classification_failed=true, which the escalation step catches.
// Mode: Run Once for Each Item
const ctx = $('Build Classification Prompt').item.json;
const CATEGORIES = ['Bug Report', 'Feature Request', 'Billing Issue', 'Technical Question', 'Incident/Outage'];
const PRIORITIES = ['High', 'Medium', 'Low'];

function extractJson(text) {
  if (typeof text !== 'string') return null;
  try { return JSON.parse(text); } catch (e) {}
  const m = text.match(/\{[\s\S]*\}/);            // model wrapped JSON in prose / code fences
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return null;
}

const content = $json?.choices?.[0]?.message?.content;
const parsed = extractJson(content);
const errors = [];
if ($json.error) errors.push('llm_http_error: ' + String($json.error?.message ?? $json.error).slice(0, 160));
if (!parsed) errors.push('unparseable_llm_output');

let category = parsed?.category ?? null;
if (category && !CATEGORIES.includes(category)) {
  // tolerate case / spacing drift ("incident / outage", "bug report")
  const norm = (s) => String(s).toLowerCase().replace(/[^a-z]/g, '');
  category = CATEGORIES.find((c) => norm(c) === norm(category)) ?? null;
  if (!category) errors.push('invalid_category: ' + parsed.category);
}
let secondary = parsed?.secondary_category ?? null;
if (secondary && !CATEGORIES.includes(secondary)) secondary = null;

let priority = PRIORITIES.includes(parsed?.priority) ? parsed.priority : null;
if (parsed && !priority) errors.push('invalid_priority: ' + parsed?.priority);

let confidence = Number(parsed?.confidence);
if (!Number.isFinite(confidence)) confidence = 0;
if (confidence > 1 && confidence <= 100) confidence = confidence / 100; // model answered "85"
confidence = Math.min(1, Math.max(0, confidence));
if (!category) confidence = 0;

const { llm_request, ...rest } = ctx;
return {
  json: {
    ...rest,
    classification: {
      category,
      secondary_category: secondary,
      priority: priority ?? 'Medium',            // safe default; record is escalated anyway if parsing failed
      confidence: Math.round(confidence * 100) / 100,
      rationale: parsed?.rationale ?? null,
      classification_failed: !category,
      errors,
      model: $json?.model ?? llm_request?.model ?? null,
    },
  },
};

// Step 3a — build the enrichment + summary request.
// Mode: Run Once for Each Item
const PROMPT_VERSION = 'enrich-v4';

const SYSTEM_PROMPT = `You extract structured facts from ONE inbound ArcVault customer message so the receiving team can act without re-reading it. The message has already been classified; the category is given for context only — do not re-classify.

Rules:
- Extract only what is literally in the message. Never invent IDs, amounts, names or dates. If something is absent, use an empty list or null.
- Copy identifiers exactly as written (keep "#", URLs, codes verbatim).
- Amounts: plain numbers without symbols or thousands separators (e.g. "$1,240" -> 1240).

Return ONLY a JSON object with exactly these keys:
{
  "core_issue": "<one sentence, max 25 words, stating the problem or request in neutral third person>",
  "identifiers": [ {"type": "account_id" | "invoice_number" | "error_code" | "url" | "order_id" | "other", "value": "<verbatim>"} ],
  "amounts": [ {"value": <number>, "currency": "<ISO code, assume USD for $>", "role": "charged" | "expected" | "other"} ],
  "time_references": ["<verbatim time/date phrases, e.g. 'around 2pm EST', 'after the update last Tuesday'>"],
  "product_area": "<short noun phrase for the affected area, e.g. 'login / authentication', 'dashboard', 'audit logs', 'invoicing', 'SSO'; null if unclear>",
  "affected_scope": "single_user" | "multiple_users" | "organization" | "unknown",
  "urgency_signal": {"level": "High" | "Medium" | "Low", "evidence": "<a short verbatim quote from the customer's message that justifies the level, or 'none stated'>"},
  "summary": "<2-3 sentences for the internal team: what happened, key identifiers and amounts, and the impact only if the customer states one. Do not add generic statements that are not in the message (e.g. about customer satisfaction). No greeting, no promises to the customer.>",
  "suggested_next_action": "<one concrete first step for the receiving team>"
}

Urgency signal = how time-sensitive the customer's own words make this (blocked work, many users, deadlines, money at stake). Judge it from the message text only, not from the category.`;

let model = 'gpt-4.1-mini';
try { if ($env.LLM_MODEL) model = $env.LLM_MODEL; } catch (e) {}

const c = $json.classification;
return {
  json: {
    ...$json,
    prompt_versions: { ...$json.prompt_versions, enrichment: PROMPT_VERSION },
    llm_request: {
      model,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        {
          role: 'user',
          content: `Category: ${c.category ?? 'Unclassified'}\nSource channel: ${$json.source}\nMessage:\n"""\n${$json.raw_message}\n"""`,
        },
      ],
    },
  },
};

// Step 3b — parse enrichment output and cross-check it with deterministic regex extraction.
// Mode: Run Once for Each Item
const ctx = $('Build Enrichment Prompt').item.json;
const raw = ctx.raw_message;

function extractJson(text) {
  if (typeof text !== 'string') return null;
  try { return JSON.parse(text); } catch (e) {}
  const m = text.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return null;
}
const p = extractJson($json?.choices?.[0]?.message?.content) ?? {};
const errors = [];
if ($json.error) errors.push('llm_http_error');
if (!Object.keys(p).length) errors.push('unparseable_llm_output');

// --- deterministic extraction (safety net: the LLM sometimes drops an ID) ---
const regexIds = [];
for (const m of raw.matchAll(/(?:invoice|inv\.?)\s*#?\s*(\d{3,})/gi)) regexIds.push({ type: 'invoice_number', value: '#' + m[1] });
for (const m of raw.matchAll(/\b(?:error|status|code)\s*:?\s*([45]\d{2})\b|\b([45]\d{2})\s+error\b/gi)) regexIds.push({ type: 'error_code', value: m[1] ?? m[2] });
for (const m of raw.matchAll(/\b(?:https?:\/\/)?(?:[a-z0-9-]+\.)+[a-z]{2,}\/[^\s,;)]+/gi)) regexIds.push({ type: 'url', value: m[0].replace(/[.]$/, '') });

const llmIds = Array.isArray(p.identifiers) ? p.identifiers.filter((i) => i && i.value) : [];
// keep only LLM identifiers that actually appear in the message (blocks hallucinated IDs)
const normalise = (v) => String(v).toLowerCase().replace(/[#\s]/g, '');
const grounded = llmIds.filter((i) => normalise(raw).includes(normalise(i.value)));
if (grounded.length < llmIds.length) errors.push(`dropped_${llmIds.length - grounded.length}_ungrounded_identifier(s)`);
const seen = new Set();
const identifiers = [...grounded, ...regexIds].filter((i) => {
  const k = normalise(i.value);
  if (seen.has(k)) return false;
  seen.add(k);
  return true;
});

// amounts: LLM gives roles; regex gives a fallback list of every $ figure in the text
let amounts = Array.isArray(p.amounts)
  ? p.amounts.map((a) => ({ value: Number(String(a.value).replace(/[^0-9.]/g, '')), currency: a.currency || 'USD', role: a.role || 'other' }))
      .filter((a) => Number.isFinite(a.value))
  : [];
if (!amounts.length) {
  for (const m of raw.matchAll(/\$\s?([\d,]+(?:\.\d{1,2})?)/g)) amounts.push({ value: Number(m[1].replace(/,/g, '')), currency: 'USD', role: 'other' });
}

const LEVELS = ['High', 'Medium', 'Low'];
const urgency = p.urgency_signal && LEVELS.includes(p.urgency_signal.level)
  ? p.urgency_signal
  : { level: ctx.classification.priority, evidence: 'not extracted; defaulted to classification priority' };

const { llm_request, ...rest } = ctx;
return {
  json: {
    ...rest,
    enrichment: {
      core_issue: p.core_issue ?? raw.slice(0, 160),
      identifiers,
      amounts,
      time_references: Array.isArray(p.time_references) ? p.time_references : [],
      product_area: p.product_area ?? null,
      affected_scope: ['single_user', 'multiple_users', 'organization', 'unknown'].includes(p.affected_scope) ? p.affected_scope : 'unknown',
      urgency_signal: urgency,
      // if enrichment failed, still give the human reviewer something readable
      summary: p.summary ?? `Automatic enrichment failed for this ${ctx.source} message (category: ${ctx.classification.category ?? 'unclassified'}). Original text: "${raw.slice(0, 300)}"`,
      suggested_next_action: p.suggested_next_action ?? null,
      errors,
    },
  },
};

// Step 4 — routing decision. Deterministic: the LLM classifies, code decides where it goes.
// Mode: Run Once for Each Item
const ROUTING_TABLE = {
  'Bug Report':         { queue: 'Engineering', reason: 'Defect in product behaviour -> engineering triage' },
  'Incident/Outage':    { queue: 'Engineering', reason: 'Service degradation -> engineering on-call' },
  'Feature Request':    { queue: 'Product',     reason: 'New capability / enhancement -> product backlog' },
  'Billing Issue':      { queue: 'Billing',     reason: 'Invoice / charge / contract question -> billing ops' },
  'Technical Question': { queue: 'Support',     reason: 'How-to / integration question -> support & solutions' },
};
const CONFIDENCE_THRESHOLD = 0.70;

const c = $json.classification;
const route = ROUTING_TABLE[c.category];
let routing;
if (!route) {
  routing = { standard_queue: null, reason: 'Fallback: no valid category from classifier', fallback_applied: true };
} else if (c.confidence < CONFIDENCE_THRESHOLD) {
  routing = {
    standard_queue: route.queue,
    reason: `Fallback: confidence ${c.confidence} < ${CONFIDENCE_THRESHOLD}; best guess was ${route.queue}` +
      (c.secondary_category ? ` (alt: ${ROUTING_TABLE[c.secondary_category]?.queue ?? 'n/a'})` : ''),
    fallback_applied: true,
  };
} else {
  routing = { standard_queue: route.queue, reason: route.reason, fallback_applied: false };
}

return { json: { ...$json, routing } };

// Steps 5 + 6 — apply escalation rules, then assemble the final structured record.
// Mode: Run Once for Each Item
const CONFIDENCE_THRESHOLD = 0.70;
const BILLING_THRESHOLD_USD = 500;

// Word-boundary phrases only: a bare /down/ would match "download" and "dropdown".
const OUTAGE_PATTERNS = [
  /\boutage\b/i,
  /\b(?:is|are|was|went|been|still|completely|totally)\s+down\b/i,
  /\bdown\s+for\s+(?:all|everyone|everybody|multiple|several|our)\b/i,
  /\bstopped\s+(?:loading|working|responding)\b/i,
  /\b(?:multiple|several|many|all)\s+(?:of\s+our\s+)?users\b/i,
  /\b(?:nobody|no\s+one|none\s+of\s+us)\s+can\b/i,
];
const SECURITY_PATTERNS = [
  /\bbreach(?:ed)?\b/i, /\bhacked\b/i, /\bunauthori[sz]ed\s+access\b/i,
  /\bdata\s+leak\b/i, /\bcompromised\b/i, /\bvulnerabilit(?:y|ies)\b/i,
];

const raw = $json.raw_message;
const c = $json.classification;
const e = $json.enrichment;
const reasons = [];

// 1. Low confidence / failed classification
if (c.classification_failed) reasons.push('classification_failed');
else if (c.confidence < CONFIDENCE_THRESHOLD) reasons.push(`low_confidence (${c.confidence} < ${CONFIDENCE_THRESHOLD})`);

// 2. Outage — either the model says so, or the text does (rules run on raw text so they still work if the LLM is wrong)
const outageHits = OUTAGE_PATTERNS.map((r) => raw.match(r)?.[0]).filter(Boolean);
if (c.category === 'Incident/Outage') reasons.push('category_incident_outage');
if (outageHits.length) reasons.push(`outage_keywords: ${outageHits.map((h) => `"${h}"`).join(', ')}`);

// 3. Security
const secHits = SECURITY_PATTERNS.map((r) => raw.match(r)?.[0]).filter(Boolean);
if (secHits.length) reasons.push(`security_keywords: ${secHits.map((h) => `"${h}"`).join(', ')}`);

// 4. Billing error > $500. "Error" = disputed amount = |charged - expected| when both are known;
//    if we only know the charge, use the charge itself (conservative).
let disputedAmount = null;
if (c.category === 'Billing Issue' || c.secondary_category === 'Billing Issue') {
  const usd = e.amounts.filter((a) => (a.currency || 'USD').toUpperCase() === 'USD');
  const charged = usd.filter((a) => a.role === 'charged').map((a) => a.value);
  const expected = usd.filter((a) => a.role === 'expected').map((a) => a.value);
  if (charged.length && expected.length) disputedAmount = Math.abs(Math.max(...charged) - Math.max(...expected));
  else if (charged.length) disputedAmount = Math.max(...charged);
  else if (usd.length) disputedAmount = Math.max(...usd.map((a) => a.value));
  if (disputedAmount !== null && disputedAmount > BILLING_THRESHOLD_USD) {
    reasons.push(`billing_error_over_${BILLING_THRESHOLD_USD} ($${disputedAmount})`);
  }
}

const escalate = reasons.length > 0;
const finalQueue = escalate ? 'Escalation' : $json.routing.standard_queue;

const record = {
  request_id: $json.request_id,
  received_at: $json.received_at,
  processed_at: new Date().toISOString(),
  source: $json.source,
  customer: $json.customer,
  raw_message: raw,

  // Step 2
  category: c.category,
  secondary_category: c.secondary_category,
  priority: c.priority,
  confidence: c.confidence,
  classification_rationale: c.rationale,

  // Step 3
  core_issue: e.core_issue,
  identifiers: e.identifiers,
  amounts: e.amounts,
  disputed_amount_usd: disputedAmount,
  time_references: e.time_references,
  product_area: e.product_area,
  affected_scope: e.affected_scope,
  urgency_signal: e.urgency_signal,

  // Step 4 + 6
  standard_queue: $json.routing.standard_queue,
  routing_reason: $json.routing.reason,
  escalation_flag: escalate,
  escalation_reasons: reasons,
  destination_queue: finalQueue,

  // Step 5
  summary: e.summary,
  suggested_next_action: e.suggested_next_action,

  // audit
  meta: {
    model: c.model,
    prompt_versions: $json.prompt_versions,
    parse_errors: [...c.errors, ...e.errors],
    fallback_applied: $json.routing.fallback_applied,
  },
};

return { json: record };

// Step 5 — serialize the record as one JSON line (binary) so the file nodes can append it.
// Mode: Run Once for Each Item
const line = JSON.stringify($json) + '\n';
return {
  json: $json,
  binary: {
    data: {
      data: Buffer.from(line, 'utf8').toString('base64'),
      mimeType: 'application/x-ndjson',
      fileName: 'record.jsonl',
    },
  },
};
